import {matches} from './research-core.mjs';
export const NOTEBOOK_KEY='mansour-notebook-v1';
export function validateNotebook(value){
 if(value?.format!==NOTEBOOK_KEY||!Array.isArray(value.notes)||value.notes.length>10000)throw Error('پشتیبان دفتر معتبر نیست.');
 const ids=new Set();
 return {format:NOTEBOOK_KEY,notes:value.notes.map(n=>{
  if(typeof n.id!=='string'||!n.id||n.id.length>180||ids.has(n.id)||typeof n.title!=='string'||n.title.length>200||typeof n.text!=='string'||n.text.length>100000||typeof n.tags!=='string'||n.tags.length>500||!Number.isFinite(Date.parse(n.updatedAt)))throw Error('یک یادداشت نامعتبر در فایل وجود دارد.');
  ids.add(n.id);return {id:n.id,title:n.title,text:n.text,tags:n.tags,updatedAt:n.updatedAt,starred:n.starred===true,archived:n.archived===true,trashed:n.trashed===true};
 })};
}
export function mergeNotebook(current,incoming){
 const map=new Map(validateNotebook(current).notes.map(n=>[n.id,n]));
 for(const n of validateNotebook(incoming).notes){const old=map.get(n.id);if(!old||Date.parse(n.updatedAt)>Date.parse(old.updatedAt))map.set(n.id,n);}
 return validateNotebook({format:NOTEBOOK_KEY,notes:[...map.values()]});
}
export function createNotebook({host,toast,download,legacyNotes}){
 let model={format:NOTEBOOK_KEY,notes:[]},selected=null,filter='all',timer,dirty=false;
 host.innerHTML=`<div class="nb-heading"><div><span class="eyebrow">جایی برای اندیشه‌های شما</span><h2>دفتر منصور</h2><p>بنویس، پیوند بده، دوباره کشف کن.</p></div><button id="nb-new" class="primary">＋ یادداشت تازه</button></div>
 <div class="nb-tools"><button id="nb-backup">پشتیبان دفتر</button><button id="nb-import">ورود پشتیبان</button><button id="nb-markdown">خروجی Markdown</button><button id="nb-legacy">کپی یادداشت‌های آیات به دفتر</button><input id="nb-file" type="file" accept=".json,application/json" hidden></div>
 <div class="nb-layout"><aside class="nb-sidebar"><label for="nb-search">جست‌وجو در دفتر</label><input id="nb-search" type="search" placeholder="عنوان، متن یا برچسب…"><div class="nb-filters" role="group" aria-label="نمایش یادداشت‌ها"><button data-filter="all">همه</button><button data-filter="starred">نشان‌شده</button><button data-filter="archived">بایگانی</button><button data-filter="trash">سطل زباله</button></div><p id="nb-count" class="footnote"></p><div id="nb-list"></div></aside>
 <div class="nb-paper"><div id="nb-empty"><h3>هر پژوهش، از یک یادداشت شروع می‌شود.</h3><p>یک یادداشت تازه بساز یا یادداشت‌های آیات را به دفتر بیاور.</p></div><div id="nb-editor" hidden><label for="nb-title">عنوان یادداشت</label><input id="nb-title" maxlength="200" placeholder="عنوانی برای این اندیشه…"><label for="nb-tags">برچسب‌ها</label><input id="nb-tags" maxlength="500" placeholder="تفسیر، پژوهش، مطالعه"><div class="nb-format"><button data-wrap="**">پررنگ</button><button data-wrap="*">تأکید</button><button data-prefix="## ">عنوان</button><button data-prefix="- ">فهرست</button><button id="nb-preview-toggle" aria-pressed="false">نمای مطالعه</button></div><label for="nb-text" class="visually-hidden">متن یادداشت</label><textarea id="nb-text" maxlength="100000" placeholder="از اینجا بنویس…" spellcheck="false"></textarea><div id="nb-preview" hidden></div><div class="nb-meta"><span id="nb-save" role="status"></span><span id="nb-words"></span></div><div class="nb-tools"><button id="nb-star">نشان کردن</button><button id="nb-archive">بایگانی</button><button id="nb-trash">انتقال به سطل زباله</button><button id="nb-restore" hidden>بازیابی</button><button id="nb-delete" hidden>حذف همیشگی</button></div></div></div></div>`;
 const $=id=>host.querySelector('#'+id),current=()=>model.notes.find(n=>n.id===selected);
 try{const saved=localStorage.getItem(NOTEBOOK_KEY);if(saved)model=validateNotebook(JSON.parse(saved));}catch{host.replaceChildren(Object.assign(document.createElement('p'),{textContent:'دفتر ذخیره‌شده خوانده نشد. برای جلوگیری از بازنویسی، ویرایش غیرفعال است؛ نسخهٔ ذخیره‌شده را پشتیبان بگیرید.'}));return;}
 function save(){clearTimeout(timer);try{localStorage.setItem(NOTEBOOK_KEY,JSON.stringify(model));dirty=false;$('nb-save').textContent='روی این دستگاه ذخیره شد';return true;}catch{dirty=true;$('nb-save').textContent='ذخیره نشد؛ از دفتر پشتیبان بگیرید.';toast('فضای ذخیره‌سازی کافی نیست؛ پشتیبان دفتر را دریافت کنید.');return false;}}
 function list(){
  const query=$('nb-search').value,rows=model.notes.filter(n=>(filter==='trash'?n.trashed:!n.trashed&&(filter==='archived'?n.archived:!n.archived&&(filter!=='starred'||n.starred)))&&matches(n.title+' '+n.text+' '+n.tags,query)).sort((a,b)=>Number(b.starred)-Number(a.starred)||Date.parse(b.updatedAt)-Date.parse(a.updatedAt));
  $('nb-count').textContent=rows.length.toLocaleString('fa-IR')+' یادداشت';$('nb-list').replaceChildren();
  host.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===filter)));
  for(const n of rows){const b=document.createElement('button');b.className='nb-note';b.setAttribute('aria-current',String(n.id===selected));const t=document.createElement('strong');t.textContent=(n.starred?'★ ':'')+(n.title||'بدون عنوان');const p=document.createElement('span');p.textContent=n.text.slice(0,95)||'هنوز چیزی نوشته نشده';const meta=document.createElement('small');meta.textContent=n.tags||new Date(n.updatedAt).toLocaleDateString('fa-IR');b.append(t,p,meta);b.onclick=()=>open(n.id);$('nb-list').append(b);}
  if(!rows.length)$('nb-list').textContent='یادداشتی در این بخش پیدا نشد.';
 }
 function preview(){const text=$('nb-text').value;$('nb-words').textContent=(text.trim()?text.trim().split(/\s+/).length:0).toLocaleString('fa-IR')+' واژه';$('nb-preview').replaceChildren();for(const line of text.split('\n')){const heading=/^(#{1,3})\s+(.*)$/.exec(line),p=document.createElement(heading?'h'+(heading[1].length+1):'p');const body=heading?heading[2]:line.replace(/^- /,'• ')||'\u00a0';for(const part of body.split(/(\*\*[^*]+\*\*|\*[^*]+\*)/g)){if(part.startsWith('**')&&part.endsWith('**')){const b=document.createElement('strong');b.textContent=part.slice(2,-2);p.append(b);}else if(part.startsWith('*')&&part.endsWith('*')){const e=document.createElement('em');e.textContent=part.slice(1,-1);p.append(e);}else p.append(document.createTextNode(part));}$('nb-preview').append(p);}}
 function open(id){if(dirty)save();selected=id;const n=current();$('nb-empty').hidden=!!n;$('nb-editor').hidden=!n;if(!n){list();return;}$('nb-title').value=n.title;$('nb-text').value=n.text;$('nb-tags').value=n.tags;for(const f of ['nb-title','nb-text','nb-tags'])$(f).readOnly=n.trashed;$('nb-star').textContent=n.starred?'برداشتن نشان':'نشان کردن';$('nb-archive').textContent=n.archived?'بازگشت از بایگانی':'بایگانی';for(const f of ['nb-star','nb-archive','nb-trash'])$(f).hidden=n.trashed;for(const f of ['nb-restore','nb-delete'])$(f).hidden=!n.trashed;host.querySelectorAll('[data-wrap],[data-prefix]').forEach(b=>b.disabled=n.trashed);$('nb-save').textContent=dirty?'ذخیره نشده؛ پشتیبان بگیرید.':'ذخیره‌شده روی این دستگاه';preview();list();}
 function edit(){const n=current();if(!n||n.trashed)return;Object.assign(n,{title:$('nb-title').value,text:$('nb-text').value,tags:$('nb-tags').value,updatedAt:new Date().toISOString()});dirty=true;$('nb-save').textContent='در حال ذخیره…';clearTimeout(timer);timer=setTimeout(save,350);preview();list();}
 $('nb-new').onclick=()=>{if(dirty)save();const n={id:crypto.randomUUID(),title:'',text:'',tags:'',updatedAt:new Date().toISOString(),starred:false,archived:false,trashed:false};model.notes.push(n);filter='all';$('nb-search').value='';save();open(n.id);$('nb-preview').hidden=true;$('nb-text').hidden=false;$('nb-preview-toggle').setAttribute('aria-pressed','false');$('nb-title').focus();};
 for(const id of ['nb-title','nb-text','nb-tags'])$(id).addEventListener('input',edit);
 $('nb-search').oninput=list;host.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;list();});
 for(const [id,field] of [['nb-star','starred'],['nb-archive','archived'],['nb-trash','trashed'],['nb-restore','trashed']])$(id).onclick=()=>{const n=current();if(!n)return;n[field]=!n[field];n.updatedAt=new Date().toISOString();save();open(n.id);};
 $('nb-delete').onclick=()=>{const n=current();if(!n?.trashed||!confirm('این یادداشت برای همیشه حذف شود؟'))return;model.notes=model.notes.filter(x=>x.id!==n.id);save();open(null);};
 host.querySelectorAll('[data-wrap],[data-prefix]').forEach(b=>b.onclick=()=>{const t=$('nb-text'),start=t.selectionStart,end=t.selectionEnd,chosen=t.value.slice(start,end),mark=b.dataset.wrap;t.setRangeText(mark?mark+chosen+mark:b.dataset.prefix+chosen,start,end,'select');edit();t.focus();});
 $('nb-preview-toggle').onclick=()=>{const show=$('nb-preview').hidden;$('nb-preview').hidden=!show;$('nb-text').hidden=show;$('nb-preview-toggle').setAttribute('aria-pressed',String(show));preview();};
 $('nb-backup').onclick=()=>download('mansour-notebook.json',JSON.stringify(model,null,2),'application/json');
 $('nb-markdown').onclick=()=>download('mansour-notebook.md',model.notes.filter(n=>!n.trashed).map(n=>'# '+(n.title||'بدون عنوان')+'\n\n'+n.text+'\n\nبرچسب‌ها: '+n.tags).join('\n\n---\n\n'),'text/markdown;charset=utf-8');
 $('nb-import').onclick=()=>$('nb-file').click();$('nb-file').onchange=async()=>{try{const file=$('nb-file').files[0];if(!file)return;if(file.size>20e6)throw Error('فایل پشتیبان بیش از ۲۰ مگابایت است.');model=mergeNotebook(model,JSON.parse(await file.text()));save();open(selected||model.notes[0]?.id);toast('پشتیبان با دفتر ادغام شد.');}catch(e){toast(e.message);}finally{$('nb-file').value='';}};
 $('nb-legacy').onclick=()=>{let count=0;for(const n of legacyNotes()){const id='verse-'+n.id;if(model.notes.some(x=>x.id===id))continue;model.notes.push({id,title:n.label||'یادداشت آیهٔ '+n.ayahId,text:n.text,tags:'یادداشت آیه',updatedAt:new Date().toISOString(),starred:false,archived:false,trashed:false});count++;}save();open(selected||model.notes[0]?.id);toast(count.toLocaleString('fa-IR')+' یادداشت آیه کپی شد؛ اصل یادداشت‌ها حفظ شد.');};
 document.addEventListener('visibilitychange',()=>{if(document.hidden&&dirty)save();});window.addEventListener('beforeunload',e=>{if(dirty&&!save()){e.preventDefault();e.returnValue='';}});
 open(model.notes.find(n=>!n.trashed)?.id);
}
